violating:
import { Data, Effect, FileSystem } from "effect"

export interface InventorySnapshot {
  readonly capturedAt: string
  readonly items: ReadonlyArray<{
    readonly sku: string
    readonly quantity: number
  }>
  readonly metadata: Readonly<Record<string, unknown>>
}

export class SaveSnapshotError extends Data.TaggedError("SaveSnapshotError")<{
  readonly path: string
  readonly cause: unknown
}> {}

/** Fails with SaveSnapshotError on any failure saving the inventory snapshot. */
export const saveSnapshot = (
  directory: string,
  snapshot: InventorySnapshot
) => {
  const path = `${directory}/inventory.json`

  return Effect.gen(function*() {
    const fs = yield* FileSystem.FileSystem
    const encoded = yield* Effect.try({
      try: () => JSON.stringify(snapshot, null, 2),
      catch: (cause) => cause
    })

    yield* fs.makeDirectory(directory, { recursive: true })
    yield* fs.writeFileString(path, encoded).pipe(
      Effect.mapError((cause) => new SaveSnapshotError({ path, cause }))
    )

    return path
  })
}

